<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free PDF File Info','description'=>'Inspect PDF filename, MIME type and byte size instantly.','url'=>'https://smarttoolz.in/tools/pdf-file-info/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>PDF File Info</h1><p>Inspect basic information about a PDF file.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="f" type="file" accept="application/pdf"><pre id="o"></pre></div></section></main><script>f.onchange=()=>{let x=f.files[0];o.textContent=x?`Name: ${x.name}\nType: ${x.type||'application/pdf'}\nSize: ${x.size.toLocaleString()} bytes\nLast modified: ${new Date(x.lastModified).toLocaleString()}`:''}</script><?php smarttoolz_tool_page_end(); ?>